/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"production-level-10","number":10,"title":"Module 10 — Arrangement Labs: Rock, Pop, Country","skillBand":"Textbook","duration":"From the course textbook","summary":"- Scaffold the classic Intro–Verse–Chorus–Bridge–Outro form with timeline Locators. - Modulate dynamic lyric energy in Verse 2 while retaining foundational rhythm track lock.","modules":[{"id":"production-m-10-1","code":"10","title":"Arrangement Genre Labs: Linear Pop, Rock, and Country","blurb":"- Scaffold the classic Intro–Verse–Chorus–Bridge–Outro form with timeline Locators. - Modulate dynamic lyric energy in Verse 2 while retaining foundational rhythm track lock.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"production-l-o-14","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 10 — Arrangement Genre Labs: Linear Pop, Rock, and Country","level":1},{"type":"callout","variant":"key","title":"Note","html":"[!NOTE] <strong>Genre Labs — Skip Anytime.</strong>   Completing or skipping these labs does not block course progression or capstone deliverables."},{"type":"prose","html":"<strong>Intent:</strong> Explore linear arrangement workflows across organic, radio, and narrative forms. Master multi-mic live tracking emulation, guitar/lead overdubbing, verse storytelling dynamics, instrumental solo placement, radio length trimming, and strophic (AAA) folk forms on the horizontal ruler.   <strong>Primary Source References:</strong> John Covach (<em>Form in Rock Music: A Primer</em>); Jason Blume (<em>6 Steps to Songwriting Success</em>, <em>songwriting.net</em>); Asaf Peres (<em>Top40 Theory: The Post-Chorus and Modern Pop Architecture</em>); <em>Music-Production-Songwriting-Knowledgebase.md</em> (§8.7, §9.4); Wikipedia (<em>Verse-Chorus Form</em>, <em>32-bar Form</em>, <em>Solo (music)</em>, <em>Strophic Form</em>)."},{"type":"heading","text":"Section 10.1 — G-ROCK · Rock / Indie (skippable)","level":1},{"type":"prose","html":"<strong>Section ID:</strong> <code>production-m10-1</code>   <strong>Learning Outcomes:</strong>"},{"type":"list","items":["Scaffold the classic Intro–Verse–Chorus–Bridge–Outro form with timeline Locators.","Modulate dynamic lyric energy in Verse 2 while retaining foundational rhythm track lock.","Integrate an instrumental guitar or synth solo as the harmonic apex of the Bridge.","Overdub live rhythm guitar takes using MIDI Overdub and audio punch-in.","Mix keyboard beds and synth pads as supporting acoustic depth rather than focal leads.","Program authentic acoustic drum fills and turnaround crashes into chorus downbeats.","Construct a 64-bar linear rock arrangement."],"ordered":false}]}],"minutes":8},{"id":"production-l10-1-1","title":"10.1.1 — Intro–Verse–Chorus–Bridge–Outro on Locators","blocks":[{"type":"step","title":"10.1.1 — Intro–Verse–Chorus–Bridge–Outro on Locators","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Scaffold classic rock/indie form using timeline locators and dynamic tempo anchoring.  "}]},{"type":"step","title":"1. Rock Form Architecture (Covach)","blocks":[{"type":"prose","html":"Rock and Indie arrangement relies on high dynamic contrast between dry, intimate verses and explosive, wide, distorted choruses:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph LR\n    Intro[\"01_Intro&lt;br&gt;Bars 1–8&lt;br&gt;Clean Riff\"] --&gt; V1[\"02_Verse_1&lt;br&gt;Bars 9–24&lt;br&gt;Bass &amp; Drums Lock\"]\n    V1 --&gt; C1[\"03_Chorus_1&lt;br&gt;Bars 25–32&lt;br&gt;Wall of Guitars\"]\n    C1 --&gt; V2[\"04_Verse_2&lt;br&gt;Bars 33–40&lt;br&gt;Driving 8th Hats\"]\n    V2 --&gt; C2[\"05_Chorus_2&lt;br&gt;Bars 41–48&lt;br&gt;Double Guitars\"]\n    C2 --&gt; Bridge[\"06_Solo_Bridge&lt;br&gt;Bars 49–64&lt;br&gt;Guitar Solo\"]\n    Bridge --&gt; Climax[\"07_Final_Chorus&lt;br&gt;Bars 65–80&lt;br&gt;Max Energy\"]\n    Climax --&gt; Outro[\"08_Outro&lt;br&gt;Bars 81–88&lt;br&gt;Riff Decrescendo\"]</pre>"}]},{"type":"step","title":"2. Scaffold Setup in Live 12","blocks":[{"type":"list","items":["Set project tempo (e.g., 136.0 BPM).","Drop Locators on the Beat-Time Ruler matching the 8-bar boundaries above.","Color-code sections: Verses (Blue), Choruses (Red), Solo Bridge (Orange), Intro/Outro (Grey)."],"ordered":true}]}],"minutes":8},{"id":"production-l10-1-2","title":"10.1.2 — Second Verse: New Lyric Energy, Same Locator Type","blocks":[{"type":"step","title":"10.1.2 — Second Verse: New Lyric Energy, Same Locator Type","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Advance narrative urgency in Verse 2 without altering the underlying metric grid.  "}]},{"type":"step","title":"1. The Dynamic Verse 2 Principle","blocks":[{"type":"prose","html":"In rock songwriting, repeating Verse 1 verbatim causes the track to stall:"},{"type":"list","items":["<strong>Rhythm Section</strong>: Keep kick and bass patterns identical to maintain groove stability.","<strong>Added Energy Levers</strong>:","Open the hi-hat pedal from tightly closed 8ths to sloshy, half-open 8th notes.","Introduce a clean single-coil guitar lick or Rhodes piano chord stab on the offbeats.","Elevate vocal delivery from conversational speaking tone to chest-voice urgency."],"ordered":false}]}],"minutes":8},{"id":"production-l10-1-3","title":"10.1.3 — The Instrumental Solo Locator","blocks":[{"type":"step","title":"10.1.3 — The Instrumental Solo Locator","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct an expressive instrumental solo section following Chorus 2.  "}]},{"type":"step","title":"1. Solo Placement and Harmonic Modulation","blocks":[{"type":"prose","html":"In classic rock and indie tradition (Covach), the instrumental solo occurs directly after Chorus 2 (Bars 49–64):"},{"type":"list","items":["<strong>Harmonic Bed</strong>: Shift the rhythm section chords to the relative minor or subdominant IV chord to create a distinct harmonic platform.","<strong>Instrument Selection</strong>: Arm Track 4 (<code>LEAD_GUITAR</code> or <code>DRIFT_SYNTH_LEAD</code>).","<strong>Performance Execution</strong>: Begin the solo in a lower register (G3–D4) with rhythmic space, climbing to screaming high-register bends (A4–E5) on Bars 61–64 to set up the final chorus explosion."],"ordered":false}]}],"minutes":8},{"id":"production-l10-1-4","title":"10.1.4 — Overdubbing Guitar and Lead Lines","blocks":[{"type":"step","title":"10.1.4 — Overdubbing Guitar and Lead Lines","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Capture live overdub passes using Live's Punch-In markers and MIDI overdub.  "}]},{"type":"step","title":"1. Punch-In / Punch-Out Recording","blocks":[{"type":"prose","html":"To fix a 2-bar guitar mistake without re-recording an entire 64-bar take:"},{"type":"list","items":["In Live's Control Bar, activate the <strong>Punch-In</strong> and <strong>Punch-Out</strong> switches (beside the Loop toggle).","Set the Loop Brace precisely over Bars 15–16.","Start playback at Bar 13 (giving yourself 2 bars of pre-roll to hear the groove).","Live plays the track without recording until the playhead hits Bar 15.1.1, punches into record mode for 2 bars, and punches out cleanly at Bar 17.1.1."],"ordered":true}]}],"minutes":8},{"id":"production-l10-1-5","title":"10.1.5 — Pads and Keys as Beds, Not Heroes","blocks":[{"type":"step","title":"10.1.5 — Pads and Keys as Beds, Not Heroes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Mix acoustic pianos, organs, and synth pads as spatial support layers.  "}]},{"type":"step","title":"1. Spectral Headroom for Live Guitars","blocks":[{"type":"prose","html":"Rock mixes are dominated by mid-range electric guitars (500 Hz to 4 kHz) and vocal transients:"},{"type":"list","items":["Background organs and synth pads must NOT fight the guitar frequencies.","High-pass filter pads at 300 Hz to avoid muddying the bass guitar.","Low-pass filter pads at 6 kHz to leave air for cymbal overtones.","Set track fader to -14 dBFS to provide warm harmonic depth without drawing listener attention away from the guitars."],"ordered":false}]}],"minutes":8},{"id":"production-l10-1-6","title":"10.1.6 — Acoustic Drum Fills Cascading into Chorus Downbeats","blocks":[{"type":"step","title":"10.1.6 — Acoustic Drum Fills Cascading into Chorus Downbeats","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Program realistic acoustic drum turnaround fills with dynamic velocity grading.  "}]},{"type":"step","title":"1. Anatomical Drummer Mechanics","blocks":[{"type":"prose","html":"A real drummer has two arms and two legs. An authentic drum fill cannot have a ride cymbal, hi-hat, snare roll, and two tom hits happening simultaneously."},{"type":"list","items":["<strong>Turnaround Fill Construction on Bar 24</strong>:","Beats 1–2: Normal kick and snare backbeat.","Beat 3: High Tom hit (Velocity: 90)  Mid Tom hit (Velocity: 100).","Beat 4: Low Floor Tom hit (Velocity: 110)  Snare Flam (Velocity: 120)  All cymbals choked.","Bar 25 Beat 1.1.1: Detonating Crash Cymbal + Kick Drum downbeat (Velocity: 127)."],"ordered":false}]}],"minutes":8},{"id":"production-l10-1-7","title":"10.1.7 — Final Chorus Escalation: Tambourines and Top-Octaves","blocks":[{"type":"step","title":"10.1.7 — Final Chorus Escalation: Tambourines and Top-Octaves","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Apply classic rock arrangement levers to achieve peak energy on the final chorus.  "}]},{"type":"step","title":"1. The Climax Levers","blocks":[{"type":"prose","html":"On Bar 65 (Final Chorus):"},{"type":"list","items":["<strong>Tambourine / Shaker Track</strong>: Unmute a continuous 16th-note tambourine track panned 25% Right.","<strong>Top-Octave Power Chords</strong>: Add a distorted rhythm guitar layer playing octave roots an octave above the main rhythm.","<strong>Vocal Ad-Libs</strong>: Add wide-panned falsetto screaming harmonies echoing key chorus hook lines."],"ordered":true}]}],"minutes":8},{"id":"production-l10-1-8","title":"10.1.8 — 64-Bar Linear Rock Sketch Assembly","blocks":[{"type":"step","title":"10.1.8 — 64-Bar Linear Rock Sketch Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Assemble, audit, and export a complete 64-bar linear rock arrangement.  "}]},{"type":"step","title":"1. Final Assembly and Export","blocks":[{"type":"list","items":["Verify that Intro, Verse, Chorus, Solo, and Final Chorus flow without jarring acoustic transitions.","Export <code>Rock_Arrangement_Sketch_v01.wav</code> (24-bit, 44.1 kHz)."],"ordered":false}]}],"minutes":8},{"id":"production-l10-2-1","title":"10.2.1 — Linear Pop Architecture: Drawing the ABABCB Roadmap","blocks":[{"type":"step","title":"10.2.1 — Linear Pop Architecture: Drawing the ABABCB Roadmap","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct a complete commercial pop timeline from Bar 1 left-to-right.  "}]},{"type":"step","title":"1. Commercial Pop Roadmap","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph LR\n    Intro[\"01_Intro&lt;br&gt;4–8b&lt;br&gt;Hook Preview\"] --&gt; V1[\"02_Verse_1&lt;br&gt;8–16b&lt;br&gt;Story\"]\n    V1 --&gt; Pre1[\"03_Pre_1&lt;br&gt;4–8b&lt;br&gt;Ramp\"]\n    Pre1 --&gt; C1[\"04_Chorus_1&lt;br&gt;8b&lt;br&gt;Payoff\"]\n    C1 --&gt; V2[\"05_Verse_2&lt;br&gt;8b&lt;br&gt;Lean Story\"]\n    V2 --&gt; Pre2[\"06_Pre_2&lt;br&gt;4–8b&lt;br&gt;Urgent Ramp\"]\n    Pre2 --&gt; C2[\"07_Chorus_2&lt;br&gt;8b&lt;br&gt;Full Payoff\"]\n    C2 --&gt; Bridge[\"08_Bridge&lt;br&gt;8b&lt;br&gt;Harmonic Shift\"]\n    Bridge --&gt; Climax[\"09_Double_Chorus&lt;br&gt;16b&lt;br&gt;Max Energy\"]\n    Climax --&gt; Tag[\"10_Vocal_Tag&lt;br&gt;4b&lt;br&gt;Memory Anchor\"]</pre>"}]}],"minutes":8},{"id":"production-l10-2-2","title":"10.2.2 — Pre-Chorus as a Timeline Ramp (Summach)","blocks":[{"type":"step","title":"10.2.2 — Pre-Chorus as a Timeline Ramp (Summach)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Automate harmonic tension and filter cutoff sweeps across the Pre-Chorus.  "}]},{"type":"step","title":"1. The Harmonic and Acoustic Ramp (Summach / Everett)","blocks":[{"type":"list","items":["<strong>Harmonic Function</strong>: Shift chords from stable tonic prolongation (I or vi) to dominant preparation (IV V or ii V).","<strong>Acoustic Function</strong>: ","Automate <code>Auto Filter</code> low-pass cutoff sweeping from 400 Hz to 18 kHz across Bars 17–24.","Cut the kick drum for the final 2 bars.","Insert a rising snare roll accelerating from 8th notes to 16th notes."],"ordered":false}]}],"minutes":8},{"id":"production-l10-2-3","title":"10.2.3 — The Double Chorus and Vocal Tag","blocks":[{"type":"step","title":"10.2.3 — The Double Chorus and Vocal Tag","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Extend the final chorus climax and anchor memorability with a vocal tag.  "}]},{"type":"step","title":"1. Double Chorus Construction","blocks":[{"type":"list","items":["Duplicate the 8-bar Chorus block (<code>Ctrl + Shift + D</code>) to create a 16-bar final climax.","In the second 8 bars (Bars 73–80), unmute high bell synths and vocal harmony layers.","Append a 4-bar <strong>Vocal Tag</strong> (Bars 81–84): Mute all heavy drums and chords, leaving only an intimate Rhodes piano and the lead singer repeating the single main hook phrase."],"ordered":true}]}],"minutes":8},{"id":"production-l10-2-4","title":"10.2.4 — The Post-Chorus Decision (Peres Theoretical Audit)","blocks":[{"type":"step","title":"10.2.4 — The Post-Chorus Decision (Peres Theoretical Audit)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Evaluate and apply Asaf Peres's three conditions for modern post-chorus sections.  "}]},{"type":"step","title":"1. Asaf Peres Post-Chorus Framework (Top40 Theory)","blocks":[{"type":"prose","html":"A section qualifies as a true <strong>Post-Chorus</strong> only if it fulfills three musicological criteria:"},{"type":"list","items":["<strong>Structural Position</strong>: It immediately follows a fully realized Chorus.","<strong>Energy Invariant</strong>: It maintains or <em>exceeds</em> the energy level of the Chorus (it is NOT a breakdown).","<strong>Melodic / Lyrical Distinction</strong>: It features a brand-new melodic or instrumental riff (often a repetitive vocal chant or instrumental synth drop motif) rather than repeating the chorus melody."],"ordered":true}]}],"minutes":8},{"id":"production-l10-2-5","title":"10.2.5 — Trimming Toward Radio Pacing: The 0:45 Arrival Rule","blocks":[{"type":"step","title":"10.2.5 — Trimming Toward Radio Pacing: The 0:45 Arrival Rule","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Audit song timing to ensure commercial radio engagement standards.  "}]},{"type":"step","title":"1. Radio Pacing Benchmarks","blocks":[{"type":"list","items":["<strong>First Chorus Arrival</strong>: The downbeat of Chorus 1 must land between <strong>0:30 and 0:48</strong> of elapsed song time.","<strong>Total Song Runtime</strong>: Between <strong>2:30 and 3:30</strong> minutes (preventing streaming skip rates).","<em>Trimming Technique</em>: If Chorus 1 arrives at 1:15, use <strong>Delete Time (<code>Ctrl + Shift + Del</code>)</strong> to slice 8 bars out of Verse 1."],"ordered":false}]}],"minutes":8},{"id":"production-l10-2-6","title":"10.2.6 — Comping the Pop Topline in Live 12 Take Lanes","blocks":[{"type":"step","title":"10.2.6 — Comping the Pop Topline in Live 12 Take Lanes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Build a pristine radio vocal lead from multiple takes.  "}]},{"type":"step","title":"1. Topline Comping Protocol","blocks":[{"type":"list","items":["Record 4 takes of the lead vocal over the Pop arrangement.","Open Take Lanes (<code>Ctrl + Alt + U</code>).","Select the best vowel pronunciation, dynamic consonants, and emotional delivery for each lyrical line.","Promote selections to the Main Lane using the Draw Tool (<code>B</code>)."],"ordered":true}]}],"minutes":8},{"id":"production-l10-2-7","title":"10.2.7 — Plotting the Knowledgebase Energy Percentages","blocks":[{"type":"step","title":"10.2.7 — Plotting the Knowledgebase Energy Percentages","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Verify arrangement dynamic contours against the master songwriting table.  "}]},{"type":"step","title":"1. The Mathematical Pop Energy Profile","blocks":[{"type":"list","items":["<code>Intro</code>: 40%","<code>Verse 1</code>: 55%","<code>Pre-Chorus 1</code>: 75%","<code>Chorus 1</code>: 90%","<code>Verse 2</code>: 60%","<code>Pre-Chorus 2</code>: 80%","<code>Chorus 2</code>: 90%","<code>Bridge</code>: 35%","<code>Double Chorus Climax</code>: 100%","<code>Vocal Tag / Outro</code>: 30%"],"ordered":false}]}],"minutes":8},{"id":"production-l10-2-8","title":"10.2.8 — 64-Bar Pop Radio Edit Assembly","blocks":[{"type":"step","title":"10.2.8 — 64-Bar Pop Radio Edit Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Finalize, audit, and export the commercial pop linear arrangement.  "}]},{"type":"step","title":"1. Export Verification","blocks":[{"type":"prose","html":"Export <code>Pop_Radio_Edit_v01.wav</code> (24-bit, 44.1 kHz). Confirm that the first chorus lands before 0:45 and total runtime is under 3:30."}]}],"minutes":8},{"id":"production-l10-3-1","title":"10.3.1 — Story Verses vs. Anthem Chorus Architecture","blocks":[{"type":"step","title":"10.3.1 — Story Verses vs. Anthem Chorus Architecture","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Structure acoustic dynamics between narrative verses and melodic choruses.  "}]},{"type":"step","title":"1. Narrative Songwriting Dynamics (Jason Blume)","blocks":[{"type":"prose","html":"In Country and Folk-Pop production:"},{"type":"list","items":["<strong>The Verse</strong>: Focuses on concrete, sensory lyrical storytelling (who, what, where, when). Musically sparse: acoustic guitar fingerpicking and an intimate bassline.","<strong>The Chorus</strong>: Delivers the universal emotional revelation (the \"why\"). Musically explosive: acoustic strumming doubled by electric slide guitars, pedal steel, bass, and rich three-part vocal harmonies."],"ordered":false}]}],"minutes":8},{"id":"production-l10-3-2","title":"10.3.2 — The Acoustic Turnaround / Solo Locator","blocks":[{"type":"step","title":"10.3.2 — The Acoustic Turnaround / Solo Locator","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Insert 2-bar and 4-bar instrumental turnarounds between verses.  "}]},{"type":"step","title":"1. The Turnaround Function","blocks":[{"type":"prose","html":"In traditional country and folk forms, placing a 2-bar or 4-bar instrumental riff (acoustic guitar, fiddle, or mandolin) between Verse 1 and Verse 2 allows the listener to digest the narrative lyrics before the next verse begins."}]}],"minutes":8},{"id":"production-l10-3-3","title":"10.3.3 — Recording Continuous Linear Acoustic Takes","blocks":[{"type":"step","title":"10.3.3 — Recording Continuous Linear Acoustic Takes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Capture organic, human rhythmic pocket across the linear timeline.  "}]},{"type":"step","title":"1. Organic Rhythm Tracking","blocks":[{"type":"prose","html":"Avoid heavy grid quantization. Record an unbroken 64-bar acoustic guitar performance to anchor the track with natural micro-timing and authentic human emotion."}]}],"minutes":8},{"id":"production-l10-3-4","title":"10.3.4 — Strophic Cousin: When There Is No Chorus (AAA Form)","blocks":[{"type":"step","title":"10.3.4 — Strophic Cousin: When There Is No Chorus (AAA Form)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Analyze and construct strophic folk arrangements based on recurring refrain lines.  "}]},{"type":"step","title":"1. The Strophic Architecture (Everett / Covach)","blocks":[{"type":"prose","html":"In traditional Folk, Ballads, and Blues, songs frequently omit a separate Chorus entirely:"},{"type":"list","items":["The song consists of repeating 16-bar Verses (A1, A2, A3, A4).","<strong>The Refrain Line</strong>: Every verse ends on the exact same lyrical and melodic anchor line (e.g., <em>\"The times they are a-changin'\"</em> or <em>\"Blowin' in the wind\"</em>).","<strong>Arrangement Contrast in AAA</strong>: Because the chord progression never changes, arrangement contrast must be achieved through <strong>Additive Orchestration</strong> (Verse 1 = solo guitar; Verse 2 = +bass; Verse 3 = +drums and strings; Verse 4 = +three-part harmonies)."],"ordered":false}]}],"minutes":8},{"id":"production-l10-3-4-2","title":"10.3.5 — 32-Bar Country / Folk Sketch Assembly","blocks":[{"type":"step","title":"10.3.5 — 32-Bar Country / Folk Sketch Assembly","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct a 32-bar linear timeline containing Verse 1, Turnaround, and Chorus 1.  "}]},{"type":"step","title":"1. Timeline Assembly","blocks":[{"type":"prose","html":"Set up: <code>01_Intro (4b)</code>  <code>02_Verse_1 (16b)</code>  <code>03_Turnaround (4b)</code>  <code>04_Chorus_1 (8b)</code>."}]}],"minutes":8},{"id":"production-l10-3-6","title":"10.3.6 — Written Story-vs-Hook Mapping","blocks":[{"type":"step","title":"10.3.6 — Written Story-vs-Hook Mapping","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document narrative acoustic balance in project notes.  "}]},{"type":"step","title":"1. Production Documentation","blocks":[{"type":"prose","html":"Document in <code>COUNTRY_FOLK_MAP.txt</code> how the acoustic instrumentation supported lyrical storytelling and dynamic contrast across the ruler."}]}],"minutes":8}],"exercises":[]}]};
